    "nearest-neighbor-markdown-code-2": "输入：points = [(0,0,0), (1,0,0), (5,5,5)]\n输出：indices = [1, 0, 1]",
    "nearest-neighbor-markdown-code-3": "#include <cuda_runtime.h>\n\n// points and indices are device pointers\nextern \"C\" void solve(const float* points, int* indices, int N) {}",
